export { Button, type ButtonProps } from "./Button";
export { Checkbox, type CheckboxProps } from "./Checkbox";
export { ControlGroup, type ControlGroupProps } from "./ControlGroup";
export { Radio, type RadioGroupProps, type RadioItemProps } from "./Radio";
export { Range, type RangeProps } from "./Range";
export { Switch, type SwitchProps } from "./Switch";

"use client";

import { cn } from "@/lib/utils";
import "./controls.css";

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  size?: "md" | "sm";
}

export function Button({
  children,
  className,
  disabled,
  size = "md",
  ...props
}: ButtonProps) {
  return (
    <button
      className={cn(
        "mdx-control-button",
        size === "sm" ? "mdx-control-button--sm" : "mdx-control-button--md",
        className
      )}
      disabled={disabled}
      type="button"
      {...props}
    >
      {children}
    </button>
  );
}

"use client";

import { useId } from "react";
import "./controls.css";

export interface CheckboxProps {
  "aria-label"?: string;
  checked?: boolean;
  disabled?: boolean;
  id?: string;
  label?: string;
  onChange?: (checked: boolean) => void;
}

export function Checkbox({
  id,
  label,
  "aria-label": ariaLabel,
  checked = false,
  disabled,
  onChange,
}: CheckboxProps) {
  const autoId = useId();
  const inputId = id ?? autoId;

  return (
    <div className="flex items-center gap-2">
      <input
        aria-label={ariaLabel ?? label}
        checked={checked}
        className="mdx-checkbox"
        disabled={disabled}
        id={inputId}
        onChange={(e) => onChange?.(e.target.checked)}
        type="checkbox"
      />
      {label && (
        <label
          className="cursor-pointer text-muted-foreground text-sm"
          htmlFor={inputId}
        >
          {label}
        </label>
      )}
    </div>
  );
}

import type React from "react";
import { cn } from "@/lib/utils";

export interface ControlGroupProps {
  children: React.ReactNode;
  className?: string;
  columns?: 1 | 2 | 3;
  /** Keep multi-column layout on mobile instead of collapsing to 1 column. */
  compact?: boolean;
}

export function ControlGroup({
  children,
  columns = 1,
  compact,
  className,
}: ControlGroupProps) {
  return (
    <div
      className={cn(
        "grid gap-4 text-sm",
        compact
          ? columns >= 2 && "grid-cols-2"
          : columns === 2
            ? "grid-cols-1 sm:grid-cols-2"
            : columns === 3 && "grid-cols-1 sm:grid-cols-2 lg:grid-cols-3",
        className
      )}
    >
      {children}
    </div>
  );
}

"use client";

import {
  type ChangeEvent,
  createContext,
  type ReactNode,
  useContext,
  useId,
} from "react";
import "./controls.css";

interface RadioContextValue {
  name: string;
  onChange: (e: ChangeEvent<HTMLInputElement>) => void;
}

const RadioContext = createContext<RadioContextValue | null>(null);

export interface RadioGroupProps {
  children: ReactNode;
  direction?: "horizontal" | "vertical";
  name?: string;
  onChange?: (value: string) => void;
}

function RadioGroup({
  children,
  direction = "horizontal",
  name,
  onChange,
}: RadioGroupProps) {
  const autoName = useId();
  const groupName = name ?? autoName;

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    onChange?.(e.target.value);
  };

  return (
    <RadioContext value={{ name: groupName, onChange: handleChange }}>
      <div
        className={`flex gap-3 ${direction === "vertical" ? "flex-col" : "items-center"}`}
        role="radiogroup"
      >
        {children}
      </div>
    </RadioContext>
  );
}

export interface RadioItemProps {
  "aria-label"?: string;
  checked?: boolean;
  disabled?: boolean;
  id?: string;
  label?: string;
  value: string;
}

function RadioItem({
  id,
  label,
  "aria-label": ariaLabel,
  checked = false,
  disabled,
  value,
}: RadioItemProps) {
  const autoId = useId();
  const inputId = id ?? autoId;
  const ctx = useContext(RadioContext);

  if (!ctx) {
    console.warn("Radio.Item must be rendered within a Radio.Group component!");
    return null;
  }

  return (
    <div className="flex items-center gap-2">
      <input
        aria-label={ariaLabel ?? label}
        checked={checked}
        className="mdx-radio"
        disabled={disabled}
        id={inputId}
        name={ctx.name}
        onChange={ctx.onChange}
        type="radio"
        value={value}
      />
      {label && (
        <label
          className="cursor-pointer text-muted-foreground text-sm"
          htmlFor={inputId}
        >
          {label}
        </label>
      )}
    </div>
  );
}
RadioItem.displayName = "RadioItem";

export const Radio = {
  Group: RadioGroup,
  Item: RadioItem,
};

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";
import { useDebouncedValue } from "@/hooks/useDebouncedValue";
import "./controls.css";

export interface RangeProps {
  "aria-label"?: string;
  debounce?: number;
  disabled?: boolean;
  formatValue?: (value: number) => string;
  hideDots?: boolean;
  id?: string;
  label?: string;
  max?: number;
  min?: number;
  onChange?: (value: number) => void;
  size?: "md" | "sm";
  step?: number;
  value?: number;
}

const MAX_DOTS = 25;

export function Range({
  id,
  label,
  "aria-label": ariaLabel,
  value = 50,
  min = 0,
  max = 100,
  step = 1,
  debounce = 0,
  disabled,
  onChange,
  formatValue,
  hideDots,
  size = "md",
}: RangeProps) {
  const autoId = useId();
  const inputId = id ?? autoId;

  const [localValue, setLocalValue] = useState(value);
  const debouncedValue = useDebouncedValue(localValue, debounce);
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;
  const isFirstRender = useRef(true);

  useEffect(() => {
    if (isFirstRender.current) {
      isFirstRender.current = false;
      return;
    }
    if (debounce > 0) {
      onChangeRef.current?.(debouncedValue);
    }
  }, [debouncedValue, debounce]);

  // biome-ignore lint/correctness/useExhaustiveDependencies: sync external value without re-triggering our own writes
  useEffect(() => {
    if (value !== localValue) {
      setLocalValue(value);
    }
  }, [value]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const next = Number.parseFloat(e.target.value);
    setLocalValue(next);
    if (debounce === 0) {
      onChangeRef.current?.(next);
    }
  };

  const displayValue = formatValue
    ? formatValue(localValue)
    : localValue.toFixed(2);

  const fillPct = useMemo(
    () => ((localValue - min) / (max - min)) * 100,
    [localValue, min, max]
  );

  const stepsCount = Math.floor((max - min) / step) + 1;
  const showDots = !hideDots && stepsCount <= MAX_DOTS;

  return (
    <div
      className={`mdx-slider-pill mdx-slider-pill--${size}`}
      data-disabled={disabled || undefined}
    >
      <input
        aria-label={ariaLabel ?? label ?? "Slider"}
        className="mdx-slider-input"
        disabled={disabled}
        id={inputId}
        max={max}
        min={min}
        onChange={handleChange}
        step={step}
        type="range"
        value={localValue}
      />

      <div className="mdx-slider-fill" style={{ width: `${fillPct}%` }} />

      {showDots && (
        <div className="mdx-slider-dots">
          {Array.from({ length: stepsCount }).map((_, i) => {
            const stepVal = min + i * step;
            const pos = ((stepVal - min) / (max - min)) * 100;
            const isNearEdge = pos < 2 || pos > 98;
            return (
              <div
                className="mdx-slider-dot"
                key={stepVal}
                style={{
                  left: `${pos}%`,
                  opacity: isNearEdge ? 0 : pos < fillPct ? 0.3 : 0.6,
                }}
              />
            );
          })}
        </div>
      )}

      <div className="mdx-slider-labels">
        {label && <span className="mdx-slider-label-left">{label}</span>}
        <span className="mdx-slider-label-right">{displayValue}</span>
      </div>
    </div>
  );
}

"use client";

import { useId } from "react";
import "./controls.css";

export interface SwitchProps {
  "aria-label"?: string;
  disabled?: boolean;
  id?: string;
  label?: string;
  onChange?: (toggled: boolean) => void;
  toggled?: boolean;
}

export function Switch({
  id,
  label,
  "aria-label": ariaLabel,
  toggled = false,
  disabled,
  onChange,
}: SwitchProps) {
  const autoId = useId();
  const inputId = id ?? autoId;

  return (
    <div className="flex items-center gap-2">
      <input
        aria-label={ariaLabel ?? label}
        checked={toggled}
        className="mdx-switch"
        disabled={disabled}
        id={inputId}
        onChange={(e) => onChange?.(e.target.checked)}
        type="checkbox"
      />
      {label && (
        <label
          className="cursor-pointer text-muted-foreground text-sm"
          htmlFor={inputId}
        >
          {label}
        </label>
      )}
    </div>
  );
}

/* Control primitives — ported from @maximeheckel/design-system */

/* Checkbox — 24x24 matching Maxime's original */
.mdx-checkbox {
  position: relative;
  display: inline-block;
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  margin: 0;
  -moz-appearance: none;
  -webkit-appearance: none;
  accent-color: transparent;
  cursor: pointer;
  outline: none;
  background: hsl(var(--background));
  border: 1px solid hsl(var(--border));
  border-radius: var(--radius);
  box-shadow: none;
  transition:
    background 0.3s,
    border-color 0.3s,
    box-shadow 0.2s;
}

.mdx-checkbox::after {
  position: absolute;
  top: 4px;
  left: 7px;
  display: block;
  width: 6px;
  height: 10px;
  content: "";
  border: 2px solid hsl(var(--background));
  border-top: 0;
  border-left: 0;
  opacity: 0;
  transform: rotate(20deg);
  transition:
    transform 0.3s ease,
    opacity 0.2s;
}

.mdx-checkbox:checked {
  background: hsl(var(--foreground));
  border-color: hsl(var(--foreground));
}

.mdx-checkbox:checked::after {
  opacity: 1;
  transform: rotate(43deg);
  transition:
    transform 0.6s cubic-bezier(0.2, 0.85, 0.32, 1.2) 0.1s,
    opacity 0.3s;
}

.mdx-checkbox:disabled {
  cursor: not-allowed;
  opacity: 0.4;
  filter: grayscale(0.25);
}

@media (hover: hover) and (pointer: fine) {
  .mdx-checkbox:not(:disabled):not(:checked):hover {
    border-color: hsl(var(--foreground));
  }
  .mdx-checkbox:not(:disabled):hover {
    box-shadow: 0 2px 20px 3px hsl(var(--foreground) / 0.08);
  }
}

.mdx-checkbox:focus-visible {
  border-color: hsl(var(--foreground));
  box-shadow: 0 2px 20px 3px hsl(var(--foreground) / 0.08);
}

/* Switch — 44x24 matching Maxime's original */
.mdx-switch {
  position: relative;
  display: inline-block;
  flex-shrink: 0;
  width: 44px;
  height: 24px;
  margin: 0;
  -moz-appearance: none;
  -webkit-appearance: none;
  cursor: pointer;
  outline: none;
  background: hsl(var(--muted));
  border: 1px solid hsl(var(--border));
  border-radius: 12px;
  box-shadow: none;
  transition:
    background 0.3s,
    border-color 0.3s,
    box-shadow 0.2s;
}

.mdx-switch::after {
  position: absolute;
  top: 2px;
  left: 2px;
  display: block;
  width: 18px;
  height: 18px;
  content: "";
  background: hsl(var(--muted-foreground));
  border-radius: 50%;
  transform: translateX(0);
  transition:
    transform 0.3s ease,
    background 0.3s,
    box-shadow 0.2s;
}

.mdx-switch:checked {
  background: hsl(var(--foreground));
  border-color: hsl(var(--foreground));
}

.mdx-switch:checked::after {
  background: hsl(var(--background));
  box-shadow:
    inset 0px 1px 1px rgba(255, 255, 255, 0.3),
    inset 0px -1px 0.5px rgba(0, 0, 0, 0.3);
  transform: translateX(20px);
  transition:
    transform 0.6s cubic-bezier(0.2, 0.85, 0.32, 1.2),
    background 0.3s;
}

.mdx-switch:disabled {
  cursor: not-allowed;
  opacity: 0.4;
  filter: grayscale(0.25);
}

@media (hover: hover) and (pointer: fine) {
  .mdx-switch:not(:disabled):not(:checked):hover {
    border-color: hsl(var(--foreground));
  }
  .mdx-switch:not(:disabled):hover {
    box-shadow: 0 2px 20px 3px hsl(var(--foreground) / 0.08);
  }
}

.mdx-switch:focus-visible {
  border-color: hsl(var(--foreground));
  box-shadow: 0 2px 20px 3px hsl(var(--foreground) / 0.08);
}

/* Radio — 24x24 circle, dot-in-ring checked state */
.mdx-radio {
  position: relative;
  display: inline-block;
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  margin: 0;
  -moz-appearance: none;
  -webkit-appearance: none;
  cursor: pointer;
  outline: none;
  background: hsl(var(--background));
  border: 1px solid hsl(var(--border));
  border-radius: 50%;
  box-shadow: none;
  transition:
    background 0.3s,
    border-color 0.3s,
    box-shadow 0.2s;
}

.mdx-radio::after {
  position: absolute;
  top: 0;
  left: 0;
  display: block;
  width: 22px;
  height: 22px;
  content: "";
  background: hsl(var(--background));
  border-radius: 50%;
  opacity: 0;
  transform: scale(0.7);
  transition:
    transform 0.3s ease,
    opacity 0.2s;
}

.mdx-radio:checked {
  background: hsl(var(--foreground));
  border-color: hsl(var(--foreground));
}

.mdx-radio:checked::after {
  opacity: 1;
  transform: scale(0.5);
  transition:
    transform 0.6s cubic-bezier(0.2, 0.85, 0.32, 1.2),
    opacity 0.3s;
}

.mdx-radio:disabled {
  cursor: not-allowed;
  opacity: 0.4;
  filter: grayscale(0.25);
}

@media (hover: hover) and (pointer: fine) {
  .mdx-radio:not(:disabled):not(:checked):hover {
    border-color: hsl(var(--foreground));
  }
  .mdx-radio:not(:disabled):hover {
    box-shadow: 0 2px 20px 3px hsl(var(--foreground) / 0.08);
  }
}

.mdx-radio:focus-visible {
  border-color: hsl(var(--foreground));
  box-shadow: 0 2px 20px 3px hsl(var(--foreground) / 0.08);
}

/* Range — pill slider matching blog.maximeheckel.com */
.mdx-slider-pill {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  overflow: hidden;
  touch-action: none;
  cursor: grab;
  user-select: none;
  background-color: hsl(var(--muted) / 0.5);
}

.mdx-slider-pill:active {
  cursor: grabbing;
}

.mdx-slider-pill--sm {
  height: 34px;
  border-radius: 8px;
}

.mdx-slider-pill--md {
  height: 48px;
  border-radius: 12px;
}

.mdx-slider-pill[data-disabled] {
  cursor: not-allowed;
  opacity: 0.4;
  filter: grayscale(0.25);
}

.mdx-slider-pill:has(:focus-visible) {
  outline: 2px solid hsl(var(--ring));
  outline-offset: 2px;
}

/* Invisible native input stretched over the pill */
.mdx-slider-input {
  position: absolute;
  inset: 0;
  z-index: 2;
  width: 100%;
  height: 100%;
  padding: 0;
  margin: 0;
  -moz-appearance: none;
  -webkit-appearance: none;
  cursor: inherit;
  opacity: 0;
}

/* Fill indicator with vertical line at right edge */
.mdx-slider-fill {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 0%;
  pointer-events: none;
}

.mdx-slider-fill::before {
  position: absolute;
  top: 50%;
  right: 0;
  width: 2px;
  height: 20px;
  content: "";
  background-color: hsl(var(--foreground) / 0.5);
  border-radius: 9999px;
  transform: translate(50%, -50%);
  transition: opacity 0.15s ease-in-out;
}

/* Step dots */
.mdx-slider-dots {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  pointer-events: none;
}

.mdx-slider-dot {
  position: absolute;
  width: 4px;
  height: 4px;
  background-color: hsl(var(--foreground) / 0.4);
  border-radius: 50%;
  transform: translateX(-50%);
  transition: opacity 0.2s;
}

/* Labels overlay */
.mdx-slider-labels {
  position: absolute;
  top: 50%;
  display: flex;
  justify-content: space-between;
  width: 100%;
  padding: 0 16px;
  pointer-events: none;
  transform: translateY(-50%);
}

.mdx-slider-label-left {
  font-size: 12px;
  font-weight: 500;
  color: hsl(var(--muted-foreground));
  letter-spacing: -0.022em;
  opacity: 0.9;
}

.mdx-slider-label-right {
  font-size: 12px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  color: hsl(var(--muted-foreground));
  letter-spacing: -0.022em;
  opacity: 0.9;
}

/* Button — action trigger matching pill slider dimensions */
.mdx-control-button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  cursor: pointer;
  user-select: none;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: -0.022em;
  color: hsl(var(--muted-foreground));
  background-color: hsl(var(--muted) / 0.5);
  transition:
    background-color 0.15s ease-in-out,
    color 0.15s ease-in-out;
}

.mdx-control-button--sm {
  height: 34px;
  border-radius: 8px;
}

.mdx-control-button--md {
  height: 48px;
  border-radius: 12px;
}

.mdx-control-button:disabled {
  cursor: not-allowed;
  opacity: 0.4;
  filter: grayscale(0.25);
}

@media (hover: hover) and (pointer: fine) {
  .mdx-control-button:not(:disabled):hover {
    background-color: hsl(var(--muted));
    color: hsl(var(--foreground));
  }
}

.mdx-control-button:focus-visible {
  outline: 2px solid hsl(var(--ring));
  outline-offset: 2px;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .mdx-checkbox::after,
  .mdx-checkbox:checked::after,
  .mdx-switch::after,
  .mdx-switch:checked::after,
  .mdx-radio::after,
  .mdx-radio:checked::after {
    transition: none;
  }
}
